        ru: 'В новой стране всё немного иначе: что едят на завтрак, как принято здороваться, нужно ли снимать обувь в гостях. Местные с радостью подскажут, если ты спросишь по-простому. Сегодня учимся задавать такие вопросы по-английски — спокойно и вежливо.',
        uk: 'У новій країні все трохи інакше: що їдять на сніданок, як заведено вітатися, чи треба знімати взуття в гостях. Місцеві залюбки підкажуть, якщо ти запитаєш простими словами. Сьогодні вчимося ставити такі запитання англійською — спокійно і ввічливо.',
